-- =========================================================================
-- TRƯỜNG CAO ĐẲNG CÔNG NGHỆ THÔNG TIN TP.HCM
-- KHOA CÔNG NGHỆ THÔNG TIN - ĐIỆN TỬ
-- ĐỒ ÁN MÔN HỌC: HỆ QUẢN TRỊ CƠ SỞ DỮ LIỆU
-- ĐỀ TÀI: THIẾT KẾ VÀ CÀI ĐẶT CƠ SỞ DỮ LIỆU HỆ THỐNG QUẢN LÝ NHÀ HÀNG & GỌI MÓN (ROYAL BISTRO)
-- GIẢNG VIÊN HƯỚNG DẪN: CÔ HÀ MĨ TRINH
-- =========================================================================
-- THÔNG TIN NHÓM THỰC HIỆN:
--   - Nhóm: Nhóm 05
--   - Trưởng nhóm: NGUYỄN HOÀNG HƯNG
--   - Thành viên: 
--       1. Nguyễn Hoàng Hưng (Trưởng nhóm - Khảo sát nghiệp vụ, Thiết kế CSDL 3NF, Báo cáo & Slide)
--       2. Nguyễn Hoàng Hưng - MSSV: 501250384 (Cài đặt DDL, DML 1.250+ records, Index, Transactions)
--       3. Cao Trần Xuân Diệu (Cài đặt 4 Stored Procedures, 4 Functions, Concurrency Control mô phỏng 2 Session)
-- HỆ QUẢN TRỊ CSDL: MySQL 8.0+ / MariaDB 10.4+ (Storage Engine: InnoDB, Charset: utf8mb4)
-- =========================================================================

-- =========================================================================
-- PHẦN 1: THIẾT LẬP DATABASE VÀ CẤU HÌNH MÔI TRƯỜNG
-- =========================================================================
DROP DATABASE IF EXISTS `quan_ly_nha_hang`;
CREATE DATABASE `quan_ly_nha_hang` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `quan_ly_nha_hang`;

-- Thiết lập múi giờ và chế độ kiểm tra khóa ngoại
SET NAMES utf8mb4;
SET TIME_ZONE = '+07:00';
SET FOREIGN_KEY_CHECKS = 0;

-- =========================================================================
-- PHẦN 2: TẠO CÁC BẢNG DỮ LIỆU (DDL) VÀ RÀNG BUỘC TOÀN VẸN
-- =========================================================================

-- Bảng 1: NHAN_VIEN (Quản lý danh sách nhân sự, phân quyền vai trò)
DROP TABLE IF EXISTS `nhan_vien`;
CREATE TABLE `nhan_vien` (
    `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    `ma_nv` VARCHAR(20) NOT NULL UNIQUE,
    `ho_ten` VARCHAR(100) NOT NULL,
    `chuc_vu` ENUM('QuanLy', 'ThuNgan', 'PhucVu', 'DauBep') NOT NULL DEFAULT 'PhucVu',
    `so_dien_thoai` VARCHAR(20) NOT NULL UNIQUE,
    `email` VARCHAR(100) NULL,
    `mat_khau` VARCHAR(255) NOT NULL DEFAULT '123456',
    `trang_thai` ENUM('hoat_dong', 'tam_khoa', 'da_nghi') NOT NULL DEFAULT 'hoat_dong',
    `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB COMMENT='Bảng danh mục nhân viên';

-- Bảng 2: LOAI_MON (Danh mục phân loại thực đơn)
DROP TABLE IF EXISTS `loai_mon`;
CREATE TABLE `loai_mon` (
    `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    `ma_loai` VARCHAR(20) NOT NULL UNIQUE,
    `ten_loai` VARCHAR(100) NOT NULL,
    `mo_ta` TEXT NULL,
    `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB COMMENT='Bảng danh mục loại món ăn';

-- Bảng 3: MON_AN (Thực đơn món ăn và đồ uống của nhà hàng)
DROP TABLE IF EXISTS `mon_an`;
CREATE TABLE `mon_an` (
    `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    `ma_mon` VARCHAR(20) NOT NULL UNIQUE,
    `ten_mon` VARCHAR(150) NOT NULL,
    `loai_mon_id` BIGINT UNSIGNED NULL,
    `don_gia` DOUBLE NOT NULL DEFAULT 0 CHECK (`don_gia` >= 0),
    `don_vi_tinh` VARCHAR(30) NOT NULL DEFAULT 'Phần',
    `mo_ta` TEXT NULL,
    `hinh_anh` VARCHAR(255) NULL,
    `trang_thai` ENUM('con_hang', 'tam_het', 'ngung_ban') NOT NULL DEFAULT 'con_hang',
    `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT `fk_monan_loaimon` FOREIGN KEY (`loai_mon_id`) REFERENCES `loai_mon`(`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB COMMENT='Bảng thực đơn món ăn';

-- Bảng 4: BAN_AN (Quản lý mặt bằng bàn ăn và trạng thái phục vụ)
DROP TABLE IF EXISTS `ban_an`;
CREATE TABLE `ban_an` (
    `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    `ma_ban` VARCHAR(20) NOT NULL UNIQUE,
    `ten_ban` VARCHAR(50) NOT NULL,
    `khu_vuc` VARCHAR(50) NOT NULL DEFAULT 'Tầng 1 - Sảnh Chính',
    `suc_chua` INT NOT NULL DEFAULT 4 CHECK (`suc_chua` > 0),
    `trang_thai` ENUM('trong', 'co_khach', 'da_dat') NOT NULL DEFAULT 'trong',
    `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB COMMENT='Bảng quản lý bàn ăn';

-- Bảng 5: KHACH_HANG (Quản lý khách hàng thân thiết và tích điểm CRM)
DROP TABLE IF EXISTS `khach_hang`;
CREATE TABLE `khach_hang` (
    `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    `ma_kh` VARCHAR(20) NOT NULL UNIQUE,
    `ho_ten` VARCHAR(100) NOT NULL,
    `so_dien_thoai` VARCHAR(20) NOT NULL UNIQUE,
    `email` VARCHAR(100) NULL,
    `diem_tich_luy` INT NOT NULL DEFAULT 0 CHECK (`diem_tich_luy` >= 0),
    `hang_thanh_vien` ENUM('Dong', 'Bac', 'Vang', 'KimCuong') NOT NULL DEFAULT 'Dong',
    `tong_chi_tieu` DOUBLE NOT NULL DEFAULT 0 CHECK (`tong_chi_tieu` >= 0),
    `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB COMMENT='Bảng khách hàng thân thiết CRM';

-- Bảng 6: HOA_DON (BẢNG DỮ LIỆU NGHIỆP VỤ TRỌNG TÂM - LƯU TRỮ HÓA ĐƠN BÁN HÀNG)
DROP TABLE IF EXISTS `hoa_don`;
CREATE TABLE `hoa_don` (
    `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    `ma_hd` VARCHAR(30) NOT NULL UNIQUE,
    `ban_id` BIGINT UNSIGNED NULL,
    `nhan_vien_id` BIGINT UNSIGNED NULL,
    `khach_hang_id` BIGINT UNSIGNED NULL,
    `ngay_lap` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `tong_tien_tam_tinh` DOUBLE NOT NULL DEFAULT 0 CHECK (`tong_tien_tam_tinh` >= 0),
    `tien_giam_gia` DOUBLE NOT NULL DEFAULT 0 CHECK (`tien_giam_gia` >= 0),
    `tien_thue_vat` DOUBLE NOT NULL DEFAULT 0 CHECK (`tien_thue_vat` >= 0),
    `tong_thanh_toan` DOUBLE NOT NULL DEFAULT 0 CHECK (`tong_thanh_toan` >= 0),
    `phuong_thuc_tt` ENUM('tien_mat', 'chuyen_khoan', 'the_ngan_hang', 'vi_dien_tu') NOT NULL DEFAULT 'tien_mat',
    `trang_thai_tt` ENUM('cho_thanh_toan', 'da_thanh_toan', 'da_huy') NOT NULL DEFAULT 'cho_thanh_toan',
    `ghi_chu` VARCHAR(255) NULL,
    `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT `fk_hoadon_ban` FOREIGN KEY (`ban_id`) REFERENCES `ban_an`(`id`) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT `fk_hoadon_nhanvien` FOREIGN KEY (`nhan_vien_id`) REFERENCES `nhan_vien`(`id`) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT `fk_hoadon_khachhang` FOREIGN KEY (`khach_hang_id`) REFERENCES `khach_hang`(`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB COMMENT='Bảng nghiệp vụ hóa đơn bán hàng';

-- Bảng 7: CHI_TIET_HOA_DON (BẢNG DỮ LIỆU NGHIỆP VỤ - CHI TIẾT CÁC MÓN GỌI TRONG HÓA ĐƠN)
DROP TABLE IF EXISTS `chi_tiet_hoa_don`;
CREATE TABLE `chi_tiet_hoa_don` (
    `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    `hoa_don_id` BIGINT UNSIGNED NOT NULL,
    `mon_an_id` BIGINT UNSIGNED NOT NULL,
    `so_luong` INT NOT NULL DEFAULT 1 CHECK (`so_luong` > 0),
    `don_gia` DOUBLE NOT NULL DEFAULT 0 CHECK (`don_gia` >= 0),
    `thanh_tien` DOUBLE NOT NULL DEFAULT 0 CHECK (`thanh_tien` >= 0),
    `ghi_chu` VARCHAR(255) NULL,
    `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT `fk_cthd_hoadon` FOREIGN KEY (`hoa_don_id`) REFERENCES `hoa_don`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT `fk_cthd_monan` FOREIGN KEY (`mon_an_id`) REFERENCES `mon_an`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB COMMENT='Bảng nghiệp vụ chi tiết hóa đơn gọi món';

SET FOREIGN_KEY_CHECKS = 1;

-- =========================================================================
-- PHẦN 3: TẠO CÁC CHỈ MỤC (INDEXES) TỐI ƯU HÓA TRUY VẤN
-- =========================================================================

-- Tối ưu tìm kiếm món ăn theo loại món
CREATE INDEX `idx_monan_loai` ON `mon_an`(`loai_mon_id`);

-- Tối ưu tra cứu hóa đơn theo mốc thời gian phục vụ báo cáo doanh thu
CREATE INDEX `idx_hoadon_ngaylap` ON `hoa_don`(`ngay_lap`);

-- Tối ưu lọc hóa đơn theo bàn ăn, nhân viên và khách hàng thân thiết
CREATE INDEX `idx_hoadon_ban` ON `hoa_don`(`ban_id`);
CREATE INDEX `idx_hoadon_nhanvien` ON `hoa_don`(`nhan_vien_id`);
CREATE INDEX `idx_hoadon_khachhang` ON `hoa_don`(`khach_hang_id`);
CREATE INDEX `idx_hoadon_trangthai` ON `hoa_don`(`trang_thai_tt`);

-- Tối ưu kết nối chi tiết hóa đơn và thống kê món ăn bán chạy
CREATE INDEX `idx_cthd_hoadon` ON `chi_tiet_hoa_don`(`hoa_don_id`);
CREATE INDEX `idx_cthd_monan` ON `chi_tiet_hoa_don`(`mon_an_id`);

-- Tối ưu tra cứu khách hàng qua số điện thoại khi tích điểm tại quầy
CREATE INDEX `idx_khachhang_sdt` ON `khach_hang`(`so_dien_thoai`);

