-- =========================================================================
-- PHẦN 4.2: CHÈN DỮ LIỆU BẢNG NGHIỆP VỤ HOA_DON VÀ CHI_TIET_HOA_DON (> 1.000 RECORDS)
-- =========================================================================
-- Đáp ứng yêu cầu đề tài: Bảng nghiệp vụ có số lượng dữ liệu lớn, tối thiểu 1.000 records.
-- Chúng tôi chèn 1.250 hóa đơn bán hàng thực tế trải dài trong 300 ngày gần nhất
-- kèm theo hơn 3.200 chi tiết món gọi tương ứng.




































-- =========================================================================
-- PHẦN 5: THIẾT KẾ CÁC STORED PROCEDURE PHỤC VỤ NGHIỆP VỤ HỆ THỐNG
-- =========================================================================

-- STORED PROCEDURE 1: Thêm món ăn vào hóa đơn bàn ăn (sp_ThemMonVaoHoaDon)
-- Mục đích: Tiếp nhận order từ nhân viên phục vụ, kiểm tra trạng thái món ăn có còn phục vụ,
-- tự động cộng dồn số lượng nếu món đã tồn tại trong hóa đơn hoặc thêm mới, sau đó tính lại tổng tiền.
DROP PROCEDURE IF EXISTS `sp_ThemMonVaoHoaDon`;
DELIMITER //
CREATE PROCEDURE `sp_ThemMonVaoHoaDon`(
    IN  p_hoa_don_id    BIGINT,
    IN  p_mon_an_id     BIGINT,
    IN  p_so_luong      INT,
    IN  p_ghi_chu       VARCHAR(255),
    OUT p_ma_trang_thai VARCHAR(20),
    OUT p_thong_bao     VARCHAR(255)
)
proc_label: BEGIN
    DECLARE v_trang_thai_mon VARCHAR(20);
    DECLARE v_don_gia DOUBLE;
    DECLARE v_trang_thai_hd VARCHAR(20);
    DECLARE v_cthd_id BIGINT;
    DECLARE v_so_luong_cu INT;
    DECLARE v_tong_tam_tinh DOUBLE;

    -- 1. Kiểm tra tính hợp lệ của tham số đầu vào
    IF p_so_luong <= 0 THEN
        SET p_ma_trang_thai = 'INVALID_QTY';
        SET p_thong_bao = 'Số lượng món đặt phải lớn hơn 0.';
        LEAVE proc_label;
    END IF;

    -- 2. Kiểm tra trạng thái hóa đơn
    SELECT `trang_thai_tt` INTO v_trang_thai_hd FROM `hoa_don` WHERE `id` = p_hoa_don_id;
    IF v_trang_thai_hd IS NULL THEN
        SET p_ma_trang_thai = 'HD_NOT_FOUND';
        SET p_thong_bao = 'Không tìm thấy hóa đơn yêu cầu.';
        LEAVE proc_label;
    ELSEIF v_trang_thai_hd <> 'cho_thanh_toan' THEN
        SET p_ma_trang_thai = 'HD_CLOSED';
        SET p_thong_bao = 'Hóa đơn đã thanh toán hoặc đã hủy, không thể thêm món.';
        LEAVE proc_label;
    END IF;

    -- 3. Kiểm tra trạng thái và giá của món ăn
    SELECT `trang_thai`, `don_gia` INTO v_trang_thai_mon, v_don_gia FROM `mon_an` WHERE `id` = p_mon_an_id;
    IF v_trang_thai_mon IS NULL THEN
        SET p_ma_trang_thai = 'MON_NOT_FOUND';
        SET p_thong_bao = 'Món ăn không tồn tại trong thực đơn.';
        LEAVE proc_label;
    ELSEIF v_trang_thai_mon <> 'con_hang' THEN
        SET p_ma_trang_thai = 'OUT_OF_STOCK';
        SET p_thong_bao = 'Món ăn hiện tại đã tạm hết hoặc ngừng phục vụ.';
        LEAVE proc_label;
    END IF;

    -- 4. Thêm món hoặc cộng dồn số lượng nếu đã có trong hóa đơn
    SELECT `id`, `so_luong` INTO v_cthd_id, v_so_luong_cu 
    FROM `chi_tiet_hoa_don` 
    WHERE `hoa_don_id` = p_hoa_don_id AND `mon_an_id` = p_mon_an_id 
    LIMIT 1;

    IF v_cthd_id IS NOT NULL THEN
        UPDATE `chi_tiet_hoa_don` 
        SET `so_luong` = `so_luong` + p_so_luong,
            `thanh_tien` = (`so_luong` + p_so_luong) * v_don_gia,
            `ghi_chu` = IFNULL(p_ghi_chu, `ghi_chu`)
        WHERE `id` = v_cthd_id;
    ELSE
        VALUES (p_hoa_don_id, p_mon_an_id, p_so_luong, v_don_gia, p_so_luong * v_don_gia, p_ghi_chu);
    END IF;

    -- 5. Cập nhật lại tổng tiền hóa đơn
    SELECT IFNULL(SUM(`thanh_tien`), 0) INTO v_tong_tam_tinh 
    FROM `chi_tiet_hoa_don` 
    WHERE `hoa_don_id` = p_hoa_don_id;

    UPDATE `hoa_don` 
    SET `tong_tien_tam_tinh` = v_tong_tam_tinh,
        `tien_thue_vat` = ROUND((v_tong_tam_tinh - `tien_giam_gia`) * 0.08, 0),
        `tong_thanh_toan` = (v_tong_tam_tinh - `tien_giam_gia`) + ROUND((v_tong_tam_tinh - `tien_giam_gia`) * 0.08, 0)
    WHERE `id` = p_hoa_don_id;

    SET p_ma_trang_thai = 'SUCCESS';
    SET p_thong_bao = 'Thêm món vào hóa đơn thành công!';
END //
DELIMITER ;


-- STORED PROCEDURE 2: Thanh toán hóa đơn bàn ăn & Tích điểm CRM (sp_ThanhToanHoaDon)
-- Mục đích: Quyết toán hóa đơn, trừ điểm tích lũy đổi voucher giảm giá (1 điểm = 1.000 VNĐ),
-- tính thuế VAT 8%, cập nhật trạng thái hóa đơn sang 'da_thanh_toan', tích thêm điểm thưởng mới
-- cho khách hàng theo tỷ lệ chi tiêu (100.000 VNĐ = 1 điểm) và giải phóng bàn ăn về trạng thái 'trong'.
DROP PROCEDURE IF EXISTS `sp_ThanhToanHoaDon`;
DELIMITER //
CREATE PROCEDURE `sp_ThanhToanHoaDon`(
    IN  p_hoa_don_id    BIGINT,
    IN  p_pttt          VARCHAR(50),
    IN  p_diem_su_dung  INT,
    OUT p_tong_tam_tinh DOUBLE,
    OUT p_tien_giam     DOUBLE,
    OUT p_thanh_toan    DOUBLE,
    OUT p_diem_moi      INT,
    OUT p_trang_thai    VARCHAR(20)
)
proc_label: BEGIN
    DECLARE v_ban_id BIGINT;
    DECLARE v_kh_id BIGINT;
    DECLARE v_diem_hien_co INT DEFAULT 0;
    DECLARE v_tam_tinh DOUBLE DEFAULT 0;
    DECLARE v_giam_gia DOUBLE DEFAULT 0;
    DECLARE v_vat DOUBLE DEFAULT 0;
    DECLARE v_tong_cong DOUBLE DEFAULT 0;
    DECLARE v_diem_tich_them INT DEFAULT 0;
    DECLARE v_trang_thai_hd VARCHAR(20);

    -- 1. Kiểm tra hóa đơn
    SELECT `ban_id`, `khach_hang_id`, `trang_thai_tt` 
    INTO v_ban_id, v_kh_id, v_trang_thai_hd
    FROM `hoa_don` WHERE `id` = p_hoa_don_id;

    IF v_trang_thai_hd IS NULL THEN
        SET p_trang_thai = 'HD_NOT_FOUND';
        LEAVE proc_label;
    ELSEIF v_trang_thai_hd <> 'cho_thanh_toan' THEN
        SET p_trang_thai = 'ALREADY_PAID';
        LEAVE proc_label;
    END IF;

    -- 2. Tính tổng tiền tạm tính từ chi tiết hóa đơn
    SELECT IFNULL(SUM(`thanh_tien`), 0) INTO v_tam_tinh
    FROM `chi_tiet_hoa_don`
    WHERE `hoa_don_id` = p_hoa_don_id;

    IF v_tam_tinh <= 0 THEN
        SET p_trang_thai = 'EMPTY_BILL';
        LEAVE proc_label;
    END IF;

    -- 3. Xử lý giảm trừ điểm tích lũy của khách hàng
    IF v_kh_id IS NOT NULL AND p_diem_su_dung > 0 THEN
        SELECT `diem_tich_luy` INTO v_diem_hien_co FROM `khach_hang` WHERE `id` = v_kh_id;
        IF v_diem_hien_co >= p_diem_su_dung THEN
            SET v_giam_gia = p_diem_su_dung * 1000;
            IF v_giam_gia > v_tam_tinh THEN SET v_giam_gia = v_tam_tinh; END IF;
        END IF;
    END IF;

    -- 4. Tính thuế VAT và tổng thanh toán
    SET v_vat = ROUND((v_tam_tinh - v_giam_gia) * 0.08, 0);
    SET v_tong_cong = (v_tam_tinh - v_giam_gia) + v_vat;

    -- 5. Cập nhật hóa đơn
    UPDATE `hoa_don`
    SET `tong_tien_tam_tinh` = v_tam_tinh,
        `tien_giam_gia` = v_giam_gia,
        `tien_thue_vat` = v_vat,
        `tong_thanh_toan` = v_tong_cong,
        `phuong_thuc_tt` = p_pttt,
        `trang_thai_tt` = 'da_thanh_toan'
    WHERE `id` = p_hoa_don_id;

    -- 6. Tích điểm mới và cập nhật khách hàng
    IF v_kh_id IS NOT NULL THEN
        SET v_diem_tich_them = FLOOR(v_tong_cong / 100000);
        UPDATE `khach_hang`
        SET `diem_tich_luy` = `diem_tich_luy` - p_diem_su_dung + v_diem_tich_them,
            `tong_chi_tieu` = `tong_chi_tieu` + v_tong_cong
        WHERE `id` = v_kh_id;
        SELECT `diem_tich_luy` INTO p_diem_moi FROM `khach_hang` WHERE `id` = v_kh_id;
    ELSE
        SET p_diem_moi = 0;
    END IF;

    -- 7. Giải phóng bàn ăn về trạng thái 'trong'
    IF v_ban_id IS NOT NULL THEN
        UPDATE `ban_an` SET `trang_thai` = 'trong' WHERE `id` = v_ban_id;
    END IF;

    SET p_tong_tam_tinh = v_tam_tinh;
    SET p_tien_giam = v_giam_gia;
    SET p_thanh_toan = v_tong_cong;
    SET p_trang_thai = 'SUCCESS';
END //
DELIMITER ;


-- STORED PROCEDURE 3: Báo cáo doanh thu & Top món ăn bán chạy (sp_ThongKeDoanhThuVaTopMon)
-- Mục đích: Tổng hợp báo cáo kinh doanh trong khoảng thời gian tùy chọn (Từ ngày - Đến ngày):
-- Số hóa đơn đã thanh toán, tổng doanh thu thực tế, doanh thu theo tiền mặt vs chuyển khoản,
-- và xếp hạng Top N món ăn bán chạy nhất theo số lượng và doanh số.
DROP PROCEDURE IF EXISTS `sp_ThongKeDoanhThuVaTopMon`;
DELIMITER //
CREATE PROCEDURE `sp_ThongKeDoanhThuVaTopMon`(
    IN p_tu_ngay   DATETIME,
    IN p_den_ngay  DATETIME,
    IN p_top_limit INT
)
BEGIN
    -- Tập kết quả 1: Tổng quan tài chính
    SELECT 
        COUNT(`id`) AS `tong_so_hoa_don`,
        IFNULL(SUM(`tong_thanh_toan`), 0) AS `tong_doanh_thu`,
        IFNULL(SUM(CASE WHEN `phuong_thuc_tt` = 'tien_mat' THEN `tong_thanh_toan` ELSE 0 END), 0) AS `doanh_thu_tien_mat`,
        IFNULL(SUM(CASE WHEN `phuong_thuc_tt` = 'chuyen_khoan' THEN `tong_thanh_toan` ELSE 0 END), 0) AS `doanh_thu_chuyen_khoan`,
        IFNULL(SUM(CASE WHEN `phuong_thuc_tt` IN ('the_ngan_hang', 'vi_dien_tu') THEN `tong_thanh_toan` ELSE 0 END), 0) AS `doanh_thu_the_va_vi`,
        IFNULL(ROUND(AVG(`tong_thanh_toan`), 0), 0) AS `gia_tri_trung_binh_hoa_don`
    FROM `hoa_don`
    WHERE `trang_thai_tt` = 'da_thanh_toan'
      AND `ngay_lap` BETWEEN p_tu_ngay AND p_den_ngay;

    -- Tập kết quả 2: Top N món ăn bán chạy nhất
    SELECT 
        m.`ma_mon`,
        m.`ten_mon`,
        l.`ten_loai`,
        SUM(c.`so_luong`) AS `tong_so_luong_ban`,
        SUM(c.`thanh_tien`) AS `tong_doanh_thu_mon`
    FROM `chi_tiet_hoa_don` c
    JOIN `hoa_don` h ON c.`hoa_don_id` = h.`id`
    JOIN `mon_an` m ON c.`mon_an_id` = m.`id`
    LEFT JOIN `loai_mon` l ON m.`loai_mon_id` = l.`id`
    WHERE h.`trang_thai_tt` = 'da_thanh_toan'
      AND h.`ngay_lap` BETWEEN p_tu_ngay AND p_den_ngay
    GROUP BY m.`id`, m.`ma_mon`, m.`ten_mon`, l.`ten_loai`
    ORDER BY `tong_so_luong_ban` DESC, `tong_doanh_thu_mon` DESC
    LIMIT p_top_limit;
END //
DELIMITER ;


-- STORED PROCEDURE 4: Tra cứu thực đơn và lọc món ăn linh hoạt (sp_TraCuuThucDon)
DROP PROCEDURE IF EXISTS `sp_TraCuuThucDon`;
DELIMITER //
CREATE PROCEDURE `sp_TraCuuThucDon`(
    IN p_loai_mon_id BIGINT,
    IN p_gia_min     DOUBLE,
    IN p_gia_max     DOUBLE,
    IN p_tu_khoa     VARCHAR(100)
)
BEGIN
    SELECT 
        m.`id`,
        m.`ma_mon`,
        m.`ten_mon`,
        l.`ten_loai`,
        m.`don_gia`,
        m.`don_vi_tinh`,
        m.`trang_thai`
    FROM `mon_an` m
    LEFT JOIN `loai_mon` l ON m.`loai_mon_id` = l.`id`
    WHERE (p_loai_mon_id IS NULL OR m.`loai_mon_id` = p_loai_mon_id)
      AND (p_gia_min IS NULL OR m.`don_gia` >= p_gia_min)
      AND (p_gia_max IS NULL OR m.`don_gia` <= p_gia_max)
      AND (p_tu_khoa IS NULL OR m.`ten_mon` LIKE CONCAT('%', p_tu_khoa, '%'))
    ORDER BY m.`don_gia` ASC;
END //
DELIMITER ;

-- =========================================================================
-- PHẦN 6: THIẾT KẾ CÁC FUNCTION HỖ TRỢ XỬ LÝ DỮ LIỆU
-- =========================================================================

-- FUNCTION 1: Tính số tiền thực thu sau khi trừ điểm tích lũy và cộng thuế VAT (fn_TinhTongThanhToan)
DROP FUNCTION IF EXISTS `fn_TinhTongThanhToan`;
DELIMITER //
CREATE FUNCTION `fn_TinhTongThanhToan`(
    p_tam_tinh    DOUBLE,
    p_diem_dung   INT,
    p_phan_tram_vat DOUBLE
)
RETURNS DOUBLE
DETERMINISTIC
BEGIN
    DECLARE v_tien_giam DOUBLE DEFAULT 0;
    DECLARE v_sau_giam DOUBLE DEFAULT 0;
    DECLARE v_thanh_toan DOUBLE DEFAULT 0;

    IF p_tam_tinh <= 0 THEN RETURN 0; END IF;
    SET v_tien_giam = IFNULL(p_diem_dung, 0) * 1000;
    IF v_tien_giam > p_tam_tinh THEN SET v_tien_giam = p_tam_tinh; END IF;
    SET v_sau_giam = p_tam_tinh - v_tien_giam;
    SET v_thanh_toan = v_sau_giam * (1 + IFNULL(p_phan_tram_vat, 0) / 100.0);
    RETURN ROUND(v_thanh_toan, 0);
END //
DELIMITER ;


-- FUNCTION 2: Tự động phân hạng khách hàng dựa trên lũy kế tổng chi tiêu (fn_XepHangThanhVien)
DROP FUNCTION IF EXISTS `fn_XepHangThanhVien`;
DELIMITER //
CREATE FUNCTION `fn_XepHangThanhVien`(
    p_tong_chi_tieu DOUBLE
)
RETURNS VARCHAR(20)
DETERMINISTIC
BEGIN
    IF p_tong_chi_tieu >= 25000000 THEN
        RETURN 'KimCuong';
    ELSEIF p_tong_chi_tieu >= 10000000 THEN
        RETURN 'Vang';
    ELSEIF p_tong_chi_tieu >= 3000000 THEN
        RETURN 'Bac';
    ELSE
        RETURN 'Dong';
    END IF;
END //
DELIMITER ;


-- FUNCTION 3: Kiểm tra bàn ăn có khả dụng phục vụ hay không (fn_KiemTraBanKhaDung)
DROP FUNCTION IF EXISTS `fn_KiemTraBanKhaDung`;
DELIMITER //
CREATE FUNCTION `fn_KiemTraBanKhaDung`(
    p_ban_id BIGINT
)
RETURNS TINYINT(1)
READS SQL DATA
BEGIN
    DECLARE v_trang_thai VARCHAR(20);
    SELECT `trang_thai` INTO v_trang_thai FROM `ban_an` WHERE `id` = p_ban_id;
    IF v_trang_thai = 'trong' THEN
        RETURN 1;
    ELSE
        RETURN 0;
    END IF;
END //
DELIMITER ;


-- FUNCTION 4: Tính tổng doanh thu trong một ngày cụ thể (fn_DoanhThuTheoNgay)
DROP FUNCTION IF EXISTS `fn_DoanhThuTheoNgay`;
DELIMITER //
CREATE FUNCTION `fn_DoanhThuTheoNgay`(
    p_ngay DATE
)
RETURNS DOUBLE
READS SQL DATA
BEGIN
    DECLARE v_doanh_thu DOUBLE DEFAULT 0;
    SELECT IFNULL(SUM(`tong_thanh_toan`), 0) INTO v_doanh_thu
    FROM `hoa_don`
    WHERE `trang_thai_tt` = 'da_thanh_toan'
      AND DATE(`ngay_lap`) = p_ngay;
    RETURN v_doanh_thu;
END //
DELIMITER ;

-- =========================================================================
-- PHẦN 7: THIẾT KẾ CÁC GIAO TÁC (TRANSACTION) ĐẢM BẢO TÍNH TOÀN VẸN ACID
-- =========================================================================

-- TÌNH HUỐNG GIAO TÁC 1: Mở bàn ăn và thêm các món gọi ban đầu
-- Rủi ro: Nếu bước thêm món bị lỗi (món ngưng bán) nhưng bàn ăn vẫn bị đổi thành 'co_khach'
-- hoặc tạo ra hóa đơn rỗng không có chi tiết, dữ liệu sẽ bị sai lệch.
-- Giải pháp: Đóng gói toàn bộ thao tác trong 1 Transaction, kiểm tra và ROLLBACK nếu lỗi.
START TRANSACTION;
-- Bước 1: Khóa kiểm tra bàn ăn
SELECT `id`, `trang_thai` FROM `ban_an` WHERE `id` = 1 FOR UPDATE;

-- Bước 2: Tạo hóa đơn mới cho bàn
VALUES ('HD-DEMO-TX01', 1, 3, 1, NOW(), 425000, 459000, 'cho_thanh_toan');

SET @demo_hd_id = LAST_INSERT_ID();

-- Bước 3: Thêm các chi tiết món ăn ban đầu

-- Bước 4: Chuyển trạng thái bàn sang 'co_khach'
UPDATE `ban_an` SET `trang_thai` = 'co_khach' WHERE `id` = 1;

-- Cam kết giao tác thành công toàn vẹn
COMMIT;


-- TÌNH HUỐNG GIAO TÁC 2: Quyết toán hóa đơn, trừ điểm tích lũy và giải phóng bàn ăn
-- Rủi ro: Nếu hóa đơn đổi thành 'da_thanh_toan' nhưng lỗi hệ thống mạng khiến điểm tích lũy
-- của khách không bị trừ hoặc bàn không được giải phóng, nhà hàng sẽ bị thất thoát chi phí.
-- Giải pháp: Transaction với khóa độc quyền FOR UPDATE trên cả hóa đơn và khách hàng.
START TRANSACTION;
SELECT `id`, `diem_tich_luy` FROM `khach_hang` WHERE `id` = 1 FOR UPDATE;
SELECT `id`, `tong_thanh_toan` FROM `hoa_don` WHERE `ma_hd` = 'HD-DEMO-TX01' FOR UPDATE;

-- Trừ 50 điểm thưởng (tương đương giảm 50.000 VNĐ) và cộng điểm tích lũy mới
UPDATE `khach_hang` 
SET `diem_tich_luy` = `diem_tich_luy` - 50 + FLOOR(409000 / 100000),
    `tong_chi_tieu` = `tong_chi_tieu` + 409000
WHERE `id` = 1;

-- Cập nhật trạng thái thanh toán hóa đơn
UPDATE `hoa_don`
SET `tien_giam_gia` = 50000,
    `tong_thanh_toan` = 409000,
    `phuong_thuc_tt` = 'chuyen_khoan',
    `trang_thai_tt` = 'da_thanh_toan'
WHERE `ma_hd` = 'HD-DEMO-TX01';

-- Giải phóng bàn ăn trở về trạng thái 'trong'
UPDATE `ban_an` SET `trang_thai` = 'trong' WHERE `id` = 1;

COMMIT;


-- TÌNH HUỐNG GIAO TÁC 3: Chuyển bàn / Đổi bàn ăn cho thực khách (Table Transfer)
-- Rủi ro: Khách muốn chuyển từ Bàn 02 sang Bàn 10 (VIP). Cần đảm bảo Bàn 10 đang trống,
-- chuyển hóa đơn sang Bàn 10, cập nhật Bàn 02 thành 'trong' và Bàn 10 thành 'co_khach'.
-- Nếu một trong các thao tác thất bại, hệ thống phải hoàn nguyên để không bị mất vết hóa đơn.
START TRANSACTION;
-- Khóa cả 2 bàn để ngăn chặn tranh chấp đồng thời
SELECT `id`, `trang_thai` FROM `ban_an` WHERE `id` IN (2, 10) FOR UPDATE;

-- Cập nhật hóa đơn sang bàn mới
UPDATE `hoa_don` SET `ban_id` = 10 WHERE `ban_id` = 2 AND `trang_thai_tt` = 'cho_thanh_toan';

-- Đổi trạng thái 2 bàn
UPDATE `ban_an` SET `trang_thai` = 'trong' WHERE `id` = 2;
UPDATE `ban_an` SET `trang_thai` = 'co_khach' WHERE `id` = 10;

COMMIT;

-- =========================================================================
-- PHẦN 8: VẤN ĐỀ XỬ LÝ ĐỒNG THỜI (CONCURRENCY CONTROL)
-- =========================================================================

-- TÌNH HUỐNG 1: Tranh chấp cập nhật mất dữ liệu (Lost Update)
-- Kịch bản: Hai nhân viên Thu ngân A và Phục vụ B cùng lúc mở hóa đơn Bàn 05 đang có tổng tiền 500.000 VNĐ.
-- Cả 2 cùng đọc tổng tiền cũ. Thu ngân A thêm món 100.000 VNĐ -> ghi đè 600.000 VNĐ.
-- Phục vụ B thêm món 200.000 VNĐ -> ghi đè 700.000 VNĐ. Món của Thu ngân A bị mất vĩnh viễn!
-- Giải pháp: Khóa bi quan với SELECT ... FOR UPDATE trong Transaction.

-- TÌNH HUỐNG 2: Hiện tượng đọc dữ liệu rác (Dirty Read)
-- Kịch bản: Phiên 1 thực hiện thanh toán hóa đơn tạm thời đổi trạng thái sang 'da_thanh_toan' nhưng chưa COMMIT.
-- Phiên 2 xem báo cáo doanh thu đọc được số liệu này. Sau đó Phiên 1 bị lỗi thẻ ngân hàng nên ROLLBACK.
-- Báo cáo của Phiên 2 bị sai lệch vì đọc phải dữ liệu rác không hề tồn tại.
-- Giải pháp: Mức cô lập Transaction Isolation Level tối thiểu là READ COMMITTED.

-- TÌNH HUỐNG 3: Hiện tượng bóng ma (Phantom Read)
-- Kịch bản: Quản lý đếm số hóa đơn trong ca sáng được 50 hóa đơn. Cùng lúc đó thu ngân lập hóa đơn mới và COMMIT.
-- Quản lý truy vấn lại lần 2 trong cùng 1 transaction thì thấy xuất hiện 51 hóa đơn (bóng ma xuất hiện).
-- Giải pháp: Thiết lập mức cô lập REPEATABLE READ (mặc định của InnoDB với cơ chế MVCC) hoặc SERIALIZABLE.

-- =========================================================================
-- KỊCH BẢN MÔ PHỎNG 2 SESSION CHẠY SONG SONG
-- =========================================================================
-- [HƯỚNG DẪN THỰC HÀNH]: Mở 2 cửa sổ dòng lệnh MySQL hoặc 2 tab phpMyAdmin riêng biệt:

-- === CỬA SỔ SESSION 1 ===
-- SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
-- START TRANSACTION;
-- SELECT `id`, `tong_tien_tam_tinh` FROM `hoa_don` WHERE `id` = 100 FOR UPDATE;
-- (Session 1 đang giữ khóa độc quyền Exclusive Lock trên dòng id = 100)
-- DO SLEEP(5); -- Giả lập thời gian nhân viên thao tác
-- UPDATE `hoa_don` SET `tong_tien_tam_tinh` = `tong_tien_tam_tinh` + 150000 WHERE `id` = 100;
-- COMMIT;

-- === CỬA SỔ SESSION 2 (Chạy đồng thời với Session 1) ===
-- SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
-- START TRANSACTION;
-- SELECT `id`, `tong_tien_tam_tinh` FROM `hoa_don` WHERE `id` = 100 FOR UPDATE;
-- -> KẾT QUẢ: Session 2 bị chặn lại (Lock Wait) chờ Session 1 COMMIT xong mới được đọc và xử lý tiếp.
-- -> Hiện tượng Lost Update được ngăn chặn triệt để 100%!
-- COMMIT;

-- =========================================================================
-- PHẦN 9: KIỂM TRA THỐNG KÊ SỐ LƯỢNG BẢN GHI CỦA CÁC BẢNG (VERIFICATION)
-- =========================================================================

-- Minh họa gọi Stored Procedure kiểm tra kết quả
CALL `sp_ThongKeDoanhThuVaTopMon`('2026-01-01 00:00:00', '2026-12-31 23:59:59', 5);

-- Minh họa gọi các Function kiểm tra kết quả
SELECT 
    `fn_TinhTongThanhToan`(1000000, 50, 8) AS `ThanhToan_SauGiam50k_VAT8%`,
    `fn_XepHangThanhVien`(18500000) AS `HangThanhVien_18.5Trieu`,
    `fn_KiemTraBanKhaDung`(5) AS `BanSo5_KhaDung`,
    `fn_DoanhThuTheoNgay`('2026-06-15') AS `DoanhThu_Ngay_2026-06-15`;

-- Tổng hợp số lượng bản ghi thực tế của toàn bộ CSDL
SELECT 'nhan_vien' AS `TenBang`, COUNT(*) AS `TongSoBanGhi` FROM `nhan_vien`
UNION ALL
SELECT 'loai_mon', COUNT(*) FROM `loai_mon`
UNION ALL
SELECT 'mon_an', COUNT(*) FROM `mon_an`
UNION ALL
SELECT 'ban_an', COUNT(*) FROM `ban_an`
UNION ALL
SELECT 'khach_hang', COUNT(*) FROM `khach_hang`
UNION ALL
SELECT 'hoa_don (Bảng nghiệp vụ >= 1.000 records)', COUNT(*) FROM `hoa_don`
UNION ALL
SELECT 'chi_tiet_hoa_don (Chi tiết nghiệp vụ)', COUNT(*) FROM `chi_tiet_hoa_don`;

-- =========================================================================
-- HOÀN TẤT THIẾT LẬP VÀ CÀI ĐẶT CƠ SỞ DỮ LIỆU ROYAL BISTRO
-- =========================================================================
